entries[120132] = { ["name"] = "Recipe: Secrets of Draenor Alchemy", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Teaches you how to research Secrets of Draenor Alchemy.\nAbklingzeit wird täglich abgeschlossen.\nBenötigt Alchemie von Draenor\n(1)\nVerkaufspreis:\nAlchemiegeheimnis von Draenor\nWird beim Aufheben gebunden\n\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Rezepte eingetauscht werden.\"\nVerkaufspreis:\nBenötigt Frostwurz (5)" }
entries[120134] = { ["name"] = "Recipe: Secrets of Draenor Engineering", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Teaches you how to research Secrets of Draenor Engineering.\nStellt einmal pro Tag Eure Kenntnisse der Ingenieurskunst zusammen. Geheimnisse können gegen Rezepte getauscht werden.\nBenötigt Ingenieurskunst (1)\nVerkaufspreis:\nIngenieursgeheimnis von Draenor\nWird beim Aufheben gebunden\n\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Rezepte eingetauscht werden.\"\nVerkaufspreis:\nBenötigt Echteisenerz (5)" }
entries[120135] = { ["name"] = "Recipe: Secrets of Draenor Enchanting", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Teaches you how to research Secrets of Draenor Enchanting.\nStellt einmal pro Tag Eure Kenntnisse der Verzauberkunst zusammen. Geheimnisse können gegen Rezepte getauscht werden.\nBenötigt Verzauberkunst (1)\nVerkaufspreis:\nVerzaubergeheimnis von Draenor\nWird beim Aufheben gebunden\n\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Rezepte eingetauscht werden.\"\nVerkaufspreis:\nBenötigt Draenischer Staub (3)" }
entries[120136] = { ["name"] = "Recipe: Secrets of Draenor Inscription", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Teaches you how to research Secrets of Draenor Inscription.\nStellt einmal pro Tag Eure Kenntnisse der Inschriftenkunde zusammen. Geheimnisse können gegen Rezepte getauscht werden.\nBenötigt Inschriftenkunde (1)\nVerkaufspreis:\nInschriftengeheimnis von Draenor\nWird beim Aufheben gebunden\n\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Rezepte eingetauscht werden.\"\nVerkaufspreis:\nBenötigt Himmelblaue Pigmente (2)" }
entries[120137] = { ["name"] = "Foliant der Verwandlung: Bärenjunges", ["text"] = "Klassen: Magier\nBenutzen: Lehrt Euch 'Verwandlung: Bärenjunges'.\nVerwandelt den Gegner in ein Eisbärenjunges, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:" }
entries[120138] = { ["name"] = "Foliant der Verwandlung: Affe", ["text"] = "Klassen: Magier\nBenutzen: Lehrt Euch 'Verwandlung: Affe'.\nVerwandelt den Gegner in ein Äffchen, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:" }
entries[120139] = { ["name"] = "Foliant der Verwandlung: Pinguin", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenutzen: Lehrt Euch 'Verwandlung: Pinguin'.\nVerwandelt den Gegner in einen Pinguin, der 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:" }
entries[120140] = { ["name"] = "Foliant der Verwandlung: Stachelschwein", ["text"] = "Klassen: Magier\nBenutzen: Lehrt Euch 'Verwandlung: Stachelschwein'.\nVerwandelt den Gegner in ein Stachelschwein, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:" }
