entries[120163] = { ["name"] = "Thruks Angelrute", ["text"] = "Wird beim Aufheben gebunden\nWerkzeug für Angeln Haltbarkeit 40 / 40\nAnlegen: +3 Angelfertigkeit.\nBenötigt Angeln (1)\nVerkaufspreis:" }
entries[120164] = { ["name"] = "Thruks hochbelastbare Angelrute", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n5 - 8 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[120165] = { ["name"] = "Thruks Filetiermesser", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n1 - 2 Schaden Geschwindigkeit 1.80\n(0.8 Schaden pro Sekunde)\n+8 Intelligenz\n+2 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 1 Vielseitigkeit\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[120166] = { ["name"] = "Blutbespritztes Gewand", ["text"] = "Wird beim Anlegen gebunden\nBrust Stoff\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 3 Vielseitigkeit\nHaltbarkeit 125 / 125\nVerkaufspreis:" }
entries[120167] = { ["name"] = "Blutiger Zwielichtumhang", ["text"] = "Wird beim Aufheben gebunden\nRücken\n2 Rüstung\n+2 [Beweglichkeit oder Stärke oder Intelligenz]\n+2 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 1 Vielseitigkeit\nVerkaufspreis:" }
entries[120168] = { ["name"] = "Topf Fertignudeln", ["text"] = "Völker: Pandaren , Pandaren\nBenutzen: Stellt im Verlauf von 20 Sek. Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 385 Vielseitigkeit.\n\"Einfach Wasser hinzufügen und erhitzen. Ideal für abenteuerlustige Pandaren, egal wo diese gerade unterwegs sind.\"\nVerkaufspreis:" }
entries[120169] = { ["name"] = "Schlüssel des Gezeitensteingewölbes", ["text"] = "Questgegenstand\n\"Der Schlüssel ist von all den Jahren in den feuchten Gemäuern der Akademie rostig und zerfressen.\"" }
