entries[120257] = { ["name"] = "Trommeln der Wut", ["text"] = "Benutzen: Erhöht das Nahkampf-, Distanz- und Zaubertempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren.\n\nWirkt nicht bei Verbündeten über Stufe 50. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[120258] = { ["name"] = "Muster: Trommeln der Wut", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Trommeln der Wut.\nBenötigt Lederverarbeitung von Draenor (1)\nVerkaufspreis:\nTrommeln der Wut\nBenutzen: Erhöht das Nahkampf-, Distanz- und Zaubertempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren.\n\nWirkt nicht bei Verbündeten über Stufe 50. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Rohes Tierleder (5)" }
