entries[121375] = { ["name"] = "Voos Entsafter", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n3 - 4 Schaden Geschwindigkeit 2.60\n(1.3 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n\"Keiner möchte sich vorstellen, wie man damit etwas entsaftet.\"\nVerkaufspreis:" }
entries[121376] = { ["name"] = "Klinge von Azsharas Königswache", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n\"Auch nach Tausenden Jahren ohne Gebrauch kann man noch komplizierte Muster in der Klinge des Schwertes erkennen.\"\nVerkaufspreis:" }
entries[121377] = { ["name"] = "Weggeworfene Axt des Bestienmeisters", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n2 - 5 Schaden Geschwindigkeit 2.60\n(1.3 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\n\"Anscheinend hat sich ein ziemlich großer Bär ein Stück davon abgebissen.\"\nVerkaufspreis:" }
entries[121378] = { ["name"] = "Sage von Elandrul", ["text"] = "Wird beim Aufheben gebunden\nDistanz Bogen\n4 - 6 Schaden Geschwindigkeit 3.00\n(1.7 Schaden pro Sekunde)\nHaltbarkeit 85 / 85\n\"Dieser Bogen wurde mit großer Sorgfalt geschnitzt und zeigt die lang vergangenen Taten eines elfischen Helden. Er blieb zu lang ungenutzt, um noch Spannung zu halten.\"\nVerkaufspreis:" }
entries[121379] = { ["name"] = "Mechanisierte Muskete", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n3 - 7 Schaden Geschwindigkeit 3.00\n(1.7 Schaden pro Sekunde)\nHaltbarkeit 85 / 85\n\"Kleiner als eine gewöhnliche Muskete und mit den Initialen 'A.F.' graviert.\"\nVerkaufspreis:" }
entries[121380] = { ["name"] = "Herrliches Spaltbeil", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Axt\n4 - 9 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\nHaltbarkeit 85 / 85\n\"Weggeworfen, nachdem sich der ehemalige Besitzer das einzigartige Design eingeprägt hat.\"\nVerkaufspreis:" }
entries[121381] = { ["name"] = "Schartige Kolossklinge", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\nHaltbarkeit 85 / 85\n\"Besitzt leider keine Sockel.\"\nVerkaufspreis:" }
entries[121382] = { ["name"] = "Gliederfüßlerbeinkeule", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\nHaltbarkeit 85 / 85\n\"Diese enorme Waffe besteht fast gänzlich aus dem Beinchitin einer vermutlich gewaltigen insektoiden Kreatur; die Gegengewichte bestehen aus gravierten Steinen.\"\nVerkaufspreis:" }
entries[121383] = { ["name"] = "Merkwürdiger Studentenstab von Nar'thalas", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n5 - 8 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\nHaltbarkeit 85 / 85\n\"'Wolkenmeister 9000' ist in den Schaft eingraviert und ein Büschel Pferdehaar hängt am anderen Ende. Welchem Zweck könnte das nur dienen?\"\nVerkaufspreis:" }
entries[121384] = { ["name"] = "Elementarbindungen", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Kette\n5 Rüstung\nHaltbarkeit 40 / 40\n\"Hat sich ein unbesungener Sieger wohl aus den Überresten eines mächtigen Wasserelementars geangelt.\"\nVerkaufspreis:" }
entries[121385] = { ["name"] = "Verblasster Satz Hearthstone-Karten", ["text"] = "Wird beim Aufheben gebunden\n\"Alles, was Ihr von den verblassten Karten ausmachen könnt, sind Abbilder von Bäumen mit Armen und kleine, grüne Humanoide.\"\nVerkaufspreis:" }
entries[121386] = { ["name"] = "Mandibelkordel", ["text"] = "Wird beim Aufheben gebunden\nTaille Stoff\n2 Rüstung\nHaltbarkeit 40 / 40\n\"Dieser primitive Gürtel ist aus einer Sammlung konservierter Insektenmandibeln von der Größe eines Unterarms gefertigt und als Ausrüstungsstück völlig ungeeignet.\"\nVerkaufspreis:" }
entries[121387] = { ["name"] = "Ledernes Pistolenhalfter", ["text"] = "Wird beim Aufheben gebunden\nTaille Leder\n4 Rüstung\nHaltbarkeit 40 / 40\n\"Die Extrataschen enthalten Gold und Würfel.\"\nVerkaufspreis:" }
entries[121388] = { ["name"] = "Ungesehene Bindungen", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Platte\n7 Rüstung\nHaltbarkeit 40 / 40\n\"Diese Bindungen sind stumme Zeugen des aussichtslosen Kampfes von Paladin Elund.\"\nVerkaufspreis:" }
entries[121389] = { ["name"] = "Fossiles Ei", ["text"] = "Wird beim Aufheben gebunden\n\"Dies ähnelt eher einem Obsidian als einem Edelstein und erfüllt Eure Gedanken mit einem unbestimmten Grauen, wenn Ihr es in der Hand haltet.\"\nVerkaufspreis:" }
entries[121390] = { ["name"] = "Anunds Verbände", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Stoff\n2 Rüstung\nHaltbarkeit 40 / 40\n\"Korl wird niemals zugeben, dass Anund sich mit diesen Dingern heilen und so Kaldrigos' Arkanodem überstehen wollte.\"\nVerkaufspreis:" }
entries[121391] = { ["name"] = "Giftgetränkte Manschetten", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Leder\n3 Rüstung\nHaltbarkeit 40 / 40\n\"Von einer ekelhaften Flüssigkeit und Glasscherben bedeckt.\"\nVerkaufspreis:" }
entries[121392] = { ["name"] = "Taschenübersäte Lederhose", ["text"] = "Wird beim Aufheben gebunden\nBeine Leder\n6 Rüstung\nHaltbarkeit 85 / 85\n\"Dutzende von versteckten Taschen sind über die gesamte zerfetzte Hose verteilt – jede einzelne in der perfekten Größe für einen Wurfdolch.\"\nVerkaufspreis:" }
entries[121393] = { ["name"] = "Irritierende Armada", ["text"] = "Wird beim Aufheben gebunden\nBeine Stoff\n3 Rüstung\nHaltbarkeit 85 / 85\n\"Gehörte einst einer Legende, die inzwischen wirklich tief gefallen ist.\"\nVerkaufspreis:" }
entries[121394] = { ["name"] = "Zeituhr des Schlachtzüglers", ["text"] = "Wird beim Aufheben gebunden\n\"Lasst mich nur noch fix ein paar Gegenstände und Schmuckstücke auswechseln... So! Bereit in 25... 24... 23... 22... 21...\"\nVerkaufspreis:" }
entries[121395] = { ["name"] = "Extrasaure Früchtchen", ["text"] = "Wird beim Aufheben gebunden\n\"Könnte die Leistung in besonders fordernden Dungeons deutlich steigern.\"\nVerkaufspreis:" }
entries[121396] = { ["name"] = "Brüchige Chitinschulterpolster", ["text"] = "Wird beim Aufheben gebunden\nSchulter Kette\n6 Rüstung\nHaltbarkeit 70 / 70\n\"Dieser Schulterschutz ist sogar nach azsharischer Zeitrechnung uralt und wurde mit Loasymbolen verziert.\"\nVerkaufspreis:" }
entries[121397] = { ["name"] = "Extra beschwerte Schulterpolster", ["text"] = "Wird beim Aufheben gebunden\nSchulter Leder\n4 Rüstung\nHaltbarkeit 70 / 70\n\"Was sollte wohl jemand mit so schweren Schulterpolstern anfangen?\"\nVerkaufspreis:" }
entries[121398] = { ["name"] = "Reich der Gefährten", ["text"] = "Wird beim Aufheben gebunden\nSchulter Stoff\n3 Rüstung\nHaltbarkeit 70 / 70\n\"Mutter Shahraz verteilte sie an alle, die es nicht ganz geschafft hatten.\"\nVerkaufspreis:" }
entries[121399] = { ["name"] = "Unausgewogene Glevenwerfer", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n4 Rüstung\nHaltbarkeit 40 / 40\n\"Die haben mit Sicherheit viele Fehlschläge auf dem Gewissen.\"\nVerkaufspreis:" }
entries[121400] = { ["name"] = "Shandris' fingerlose Handschuhe", ["text"] = "Wird beim Aufheben gebunden\nHände Stoff\n2 Rüstung\nHaltbarkeit 40 / 40\n\"Xalans Handschuhe standen ihr besser als ihm.\"\nVerkaufspreis:" }
entries[121401] = { ["name"] = "Handschuhe des Durchreisenden", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n4 Rüstung\nHaltbarkeit 40 / 40\n\"Ein Mann, der überall lebt, ist nirgends zu Hause.\"\nVerkaufspreis:" }
entries[121402] = { ["name"] = "Alte blutgetränkte Stulpen", ["text"] = "Wird beim Aufheben gebunden\nHände Platte\n8 Rüstung\nHaltbarkeit 40 / 40\n\"Gehörten vielleicht vor langer Zeit mal einem Metzger.\"\nVerkaufspreis:" }
entries[121403] = { ["name"] = "Zufälliger Blitzableiter", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n7 Rüstung\nHaltbarkeit 70 / 70\n\"Einige Haarbüschel sind an den Seiten festgeschmolzen.\"\nVerkaufspreis:" }
entries[121404] = { ["name"] = "Schlecht gewalzter Helm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n11 Rüstung\nHaltbarkeit 70 / 70\n\"Mangelhafte Herstellungsmethoden haben diesem Helm einen großen Teil seiner potenziellen Macht geraubt.\"\nVerkaufspreis:" }
entries[121405] = { ["name"] = "Beschädigter Berserkerplattenhelm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n11 Rüstung\nHaltbarkeit 70 / 70\n\"Da wurde jemand ziemlich wütend, während er dieses gute Stück getragen hat.\"\nVerkaufspreis:" }
entries[121406] = { ["name"] = "Zerfledderter Forscherhut", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n5 Rüstung\nHaltbarkeit 70 / 70\n\"Durch den ständigen Einsatz ziemlich abgegriffen.\"\nVerkaufspreis:" }
entries[121407] = { ["name"] = "Leere Beinplatten mit Raketenantrieb", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n12 Rüstung\nHaltbarkeit 85 / 85\n\"Sie könnten Euch nach erneuter Betankung ein ganz schönes Stück durch die Luft befördern – wären da nicht all die Teile, die bei einem vorherigen Versuch explodiert sind.\"\nVerkaufspreis:" }
entries[121408] = { ["name"] = "Pukas fehlender Ball", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses gute Stück hat jemandem einst viel bedeutet.\"\nVerkaufspreis:" }
entries[121409] = { ["name"] = "Erodierte Brustplatte", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n14 Rüstung\nHaltbarkeit 115 / 115\n\"Diese Rüstung zieren die blassen Überreste einer einst farbenfrohen Malerei, die einen Kampf zwischen hauerbewehrten Humanoiden und riesigen, gesichtslosen Kreaturen darstellt.\"\nVerkaufspreis:" }
entries[121410] = { ["name"] = "Zerfallende zeremonielle Gewänder", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n4 Rüstung\nHaltbarkeit 115 / 115\n\"Die Symbole auf dieser Robe ähneln sowohl dem Zeichen Elunes als auch dem mehrerer verehrter Loageister.\"\nVerkaufspreis:" }
entries[121411] = { ["name"] = "Wasserdurchtränktes Lederwams", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n6 Rüstung\nHaltbarkeit 115 / 115\n\"Riecht wie eine nasse Katze. Und wie ein nasser Bär. Und wie ein nasser Mondkin.\"\nVerkaufspreis:" }
entries[121412] = { ["name"] = "Leichte Plattenwanderer", ["text"] = "Wird beim Aufheben gebunden\nFüße Platte\n9 Rüstung\nHaltbarkeit 55 / 55\n\"Jemand hat auf anderem Weg herausgefunden, dass er ohne diese Dinger schneller vorankommt.\"\nVerkaufspreis:" }
entries[121413] = { ["name"] = "Zweizehige Kriegsstiefel", ["text"] = "Wird beim Aufheben gebunden\nFüße Kette\n6 Rüstung\nHaltbarkeit 55 / 55Völker: Troll\n\"Diese Stiefel wurden in der Mitte der Zehen zweigeteilt, um zwei sehr große und schmerzhaft aussehende Stacheln zu erzeugen. Jahrhunderte des Verfalls haben sie jedoch stumpf und brüchig gemacht.\"\nVerkaufspreis:" }
entries[121414] = { ["name"] = "Des Traumwebers Ignoranz", ["text"] = "Wird beim Aufheben gebunden\nFüße Stoff\n2 Rüstung\nHaltbarkeit 55 / 55\n\"Nur einmal bot ihm jemand mit einem Gegenzauber Paroli – als er diese Stiefel trug.\"\nVerkaufspreis:" }
entries[121415] = { ["name"] = "Hecates Torheit", ["text"] = "Wird beim Aufheben gebunden\nFüße Leder\n4 Rüstung\nHaltbarkeit 55 / 55\n\"Eigentlich hätte ein Hexenmeister wissen müssen, dass er diese Dinger nicht anlegen kann.\"\nVerkaufspreis:" }
