entries[121806] = { ["name"] = "Bergzornerschütterer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Eure Angriffe haben eine Chance, 'Muskelkraft des Ettin' auszulösen, die Euch 10 Sek. lang alle 0.5 Sek. 1 Stärke gewährt. (10s Abklingzeit)\nVerkaufspreis:" }
entries[121808] = { ["name"] = "Netherleiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, Euch mit Energie zu erfüllen. Nach 5 Sek. explodiert die Netherenergie und fügt Gegnern in der Nähe 5 Arkanschaden zu.\nVerkaufspreis:" }
entries[121810] = { ["name"] = "Miniatur-Leerenportal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, eine Vortexbombe auf Euer Ziel zu schleudern, die ihm und allen Gegnern in der Nähe 63 Arkanschaden zufügt.\nVerkaufspreis:" }
entries[121815] = { ["name"] = "Leerenkralle des dunklen Sterns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare Leerenkralle des dunklen Sterns oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Obwohl sie vom Einfluss des dunklen Sterns über Draenor verderbt wurden, widerstanden die Leerenkrallen den Versuchen des Schattenmondklans, sie zu brechen. Am Ende befahl Ner'zhul, sie alle auszurotten. Nur ein einziges Ei überlebte in den Weiten der Leere.\"\nBeute von:\nLeerenkrallenei" }
entries[121816] = { ["name"] = "Ungebundene Essenz", ["text"] = "Questgegenstand\n\"Diese Staubkörner sind mit ungebundener arkaner Energie gesättigt.\"" }
entries[121817] = { ["name"] = "Manarinde", ["text"] = "Questgegenstand\n\"Dir Rinde dieses Baumes wurde von reiner arkaner Energie gehärtet und kristallisiert.\"" }
entries[121818] = { ["name"] = "Buchband der Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[121819] = { ["name"] = "Forschungsnotizen", ["text"] = "Questgegenstand\n\"Diese Notizen erwähnen eine mysteriöse Maschine, die sich im oberen Skettis befindet.\"" }
entries[121820] = { ["name"] = "Gesammelte Forschungsaufzeichnungen", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Sammlung von Aufzeichnungen verrät den Zweck der mysteriösen Maschine, die sich im oberen Skettis befindet.\"\n<Zum Lesen rechtsklicken>" }
entries[121821] = { ["name"] = "Azurfokus", ["text"] = "Questgegenstand\n\"In die Struktur dieses Kristallfokus wurden machtvolle arkane Runen geschnitten, die ihn zu einer sehr starken Energiequelle machen.\"" }
entries[121822] = { ["name"] = "Notizbuchseite", ["text"] = "Questgegenstand\n\"Das scheint eine Seite aus dem Notizbuch von Val Goldschaufel zu sein.\"" }
entries[121823] = { ["name"] = "Amulett von Rukhmar", ["text"] = "Questgegenstand\nEinzigartig\n\"Es heißt, das Amulett enthält die Macht eines Gottes.\"" }
entries[121830] = { ["name"] = "Präzisionssprengpulver", ["text"] = "Questgegenstand\n\"So gefährlich wie dieses Zeug ist, hättet Ihr gedacht, dass man es sorgfältiger einpacken würde.\"" }
entries[121831] = { ["name"] = "Hochspannungszünder", ["text"] = "Questgegenstand\n\"Hoffentlich funktioniert er noch.\"" }
entries[121832] = { ["name"] = "Dämonenblut", ["text"] = "Questgegenstand\n\"Offensichtlich hat es dieses Zeug in sich.\"" }
entries[121834] = { ["name"] = "Foliant der namenlosen Leere", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Texte in diesem Buch sind nicht zu entziffern, aber es besteht kein Zweifel an der Macht, die ihnen innewohnt.\"" }
